function model(p) {
  // OAuth 2.0 authorization code flow for a mobile app (a public client with no secret), with and without PKCE.
  // A malicious app can register the same redirect scheme and grab the code (RFC 7636, section 1).
  const pkce = Math.round(p.pkce) === 1;
  const stolen = Math.round(p.stolenCode) === 1;
  const STEP = 2.5;
  const participants = [
    { id: 'U', label: 'You', actor: true },
    { id: 'A', label: 'Mobile app' },
    { id: 'B', label: 'System browser' },
    { id: 'S', label: 'Auth server' },
    { id: 'R', label: 'API' }
  ];
  if (stolen) participants.splice(3, 0, { id: 'X', label: 'Malicious app' });
  const steps = [];
  const add = (from, to, text, note, extra) => steps.push(Object.assign({ i: steps.length, from, to, text, note, reply: false }, extra || {}));
  add('U', 'A', 'Tap "Sign in"', 'You ask the app to sign you in. The app has no password field and never sees your password.');
  if (pkce) add('A', 'A', 'Make verifier + challenge', 'The app makes a random secret (code_verifier) and keeps it. It sends only its SHA-256 hash (code_challenge).', { carries: ['verifier'] });
  add('A', 'B', pkce ? 'Open /authorize + challenge' : 'Open /authorize', pkce ? 'The app opens the browser at the auth server, passing the challenge, never the verifier.' : 'The app opens the browser at the auth server. Nothing ties this request to this app.', pkce ? { carries: ['challenge'] } : {});
  add('B', 'S', 'GET /authorize', 'The browser asks the auth server for a sign-in page for this app.', pkce ? { carries: ['challenge'] } : {});
  add('S', 'U', 'Sign-in and consent page', 'You sign in on the auth server\'s own page, in the browser, not inside the app.', { reply: true });
  add('U', 'S', 'Sign in, approve', 'You sign in and approve what the app asked to access.');
  add('S', 'B', 'Redirect myapp://?code=…', 'The auth server sends a short-lived, one-time authorization code back through the browser. It is not a token.', { reply: true, carries: ['code'] });
  let tokenTo = null, rejected = false;
  if (stolen) {
    add('B', 'X', 'myapp://?code=…', 'A malicious app registered the same myapp:// scheme, so the operating system hands it the code.', { carries: ['code'], attack: true });
    add('X', 'S', 'POST /token (code)', 'The malicious app tries to trade the stolen code for a token. It never saw the verifier.', { carries: ['code'], attack: true });
    if (pkce) { rejected = true; add('S', 'X', '400 invalid_grant', 'Rejected: no code_verifier matches the challenge, so the stolen code is worthless.', { reply: true, attack: true, blocked: true }); }
    else { tokenTo = 'X'; add('S', 'X', 'Access token', 'Without PKCE nothing proves who started the sign-in, so the malicious app gets your access token.', { reply: true, carries: ['token'], attack: true }); }
  } else {
    add('B', 'A', 'myapp://?code=…', 'The operating system hands the code to the app that registered myapp://.', { carries: ['code'] });
    add('A', 'S', pkce ? 'POST /token (code + verifier)' : 'POST /token (code)', pkce ? 'The app trades the code for a token and proves it started the sign-in by sending the verifier.' : 'The app trades the code for a token. A public client has no secret, so the code alone is enough.', { carries: pkce ? ['code', 'verifier'] : ['code'] });
    if (pkce) add('S', 'S', 'SHA-256(verifier) = challenge?', 'The auth server hashes the verifier and checks it matches the challenge from the first request.');
    tokenTo = 'A';
    add('S', 'A', 'Access + refresh token', 'The tokens go straight to the app over a back-channel call, never through the browser.', { reply: true, carries: ['token'] });
    add('A', 'R', 'GET /me (Bearer token)', 'The app calls the API with the access token.', { carries: ['token'] });
    add('R', 'A', '200 your profile', 'The API checks the token and returns your data.', { reply: true });
  }
  const tokenViaBrowser = steps.some(s => (s.carries || []).includes('token') && (s.to === 'B' || s.from === 'B'));
  const duration = steps.length * STEP;
  const markers = steps.map(s => s.i * STEP);
  const markerLabels = steps.map(s => 'Step ' + (s.i + 1));
  const outcome = stolen ? (pkce ? 'The stolen code is rejected: the attacker has no verifier.' : 'The attacker swaps the stolen code for your access token.') : 'The app gets the token over a back channel; the browser only ever carries the code.';
  const summary = (pkce ? 'With PKCE' : 'Without PKCE') + (stolen ? ', code stolen. ' : ', normal sign-in. ') + outcome;
  return { participants, steps, STEP, duration, markers, markerLabels, pkce, stolen, tokenTo, rejected, tokenViaBrowser, summary };
}

checkCode:
function check(p) {
  const m = model(p);
  const pkce = Math.round(p.pkce) === 1, stolen = Math.round(p.stolenCode) === 1;
  const attackerGotToken = m.tokenTo === 'X';
  const ch = m.steps.findIndex(s => (s.carries || []).includes('challenge'));
  const sent = m.steps.filter(s => s.from !== s.to && (s.carries || []).includes('verifier'));
  const verifierSafe = sent.every(s => s.from === 'A' && s.to === 'S' && s.i > ch);
  const pass = attackerGotToken === (stolen && !pkce) && !m.tokenViaBrowser && verifierSafe;
  return { pass, detail: (pkce ? 'PKCE on' : 'PKCE off') + ', ' + (stolen ? 'code stolen' : 'no theft') + ': the attacker ' + (attackerGotToken ? 'gets' : 'does not get') + ' a token, no token passes through the browser, and the verifier ' + (sent.length ? 'goes only from the app to the auth server, after the challenge' : 'is never sent') + ' (' + m.steps.length + ' steps).' };
}
